CREATE Proc [dbo].[GetMainStoreInventoryBalanceForIssuance] @Sid as int as Select i.ItemId,i.Item, u.Unit, u.UId, ipl.Parlevel,Cast((Round((select isnull(IssFactor,0) from ItemUnit where ItemId = i.ItemId),2)) AS DECIMAL (18,2)) as Factor,iu.PurUnit as PurUnitId,(select Unit from Unit where UId = iu.PurUnit) as PurUnit From Item i inner join ItemParLevel ipl on i.ItemId=ipl.ItemId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit u on iu.IssUnit=u.Uid  inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId where  ipl.Sid = @SId and ipl.BRId=0 and i.[Type]='Non Butchery' group by i.ItemId,i.Item,u.Unit,u.UId,ipl.Parlevel,iu.PurUnit order by i.Item 